<div class="fleet-grid"><label>Billing period<select name="billing_months"><option value="1" @selected(($plan?->billing_months ?? 1) == 1)>Monthly</option><option value="12" @selected($plan?->billing_months == 12)>Yearly</option><option value="0" @selected($plan && $plan->billing_months == 0)>Legacy 30 days</option></select></label><label>Name<input name="name" value="{{ $plan?->name }}" required maxlength="100"></label><label>Price in cents (100 = 1.00)<input name="amount_cents" value="{{ $plan?->amount_cents }}" type="number" min="1" max="100000000" required></label><label>Currency code<input name="currency" value="{{ $plan?->currency ?? config('paynow.currency') }}" pattern="[A-Z]{3}" maxlength="3" placeholder="USD" required></label><label>Vehicle limit<input name="vehicle_limit" value="{{ $plan?->vehicle_limit }}" type="number" min="1" max="1000000" required></label><label>Availability<select name="is_active"><option value="0" @selected(!$plan?->is_active)>Draft / hidden</option><option value="1" @selected($plan?->is_active)>Published</option></select></label></div>
